css:
.aph-vt { font-family: "Times New Roman", Times, serif; font-size: 12.5px; color: #000; line-height: 1.35; }
.aph-vt table { width: 100%; border-collapse: collapse; font-size: inherit; }
.aph-vt .aph-head td, .aph-vt .aph-title td, .aph-vt .aph-sign td { border: 0; vertical-align: top; padding: 0; }
.aph-vt .aph-mau { width: 42%; text-align: center; font-size: 11.5px; }
.aph-vt .aph-title td { padding: 8px 0 4px; }
.aph-vt .aph-side { width: 24%; }
.aph-vt .aph-center { text-align: center; }
.aph-vt .aph-name { font-size: 17px; font-weight: bold; letter-spacing: 0.5px; }
.aph-vt .aph-date { font-style: italic; }
.aph-vt .aph-noco { padding-top: 22px !important; padding-left: 12px !important; }
.aph-vt .aph-info { margin: 4px 0 6px; line-height: 1.6; }
.aph-vt .aph-sec { font-weight: bold; margin: 10px 0 4px; }
.aph-vt .aph-tbl th, .aph-vt .aph-tbl td { border: 1px solid #000; padding: 3px 4px; }
.aph-vt .aph-tbl th { text-align: center; font-weight: bold; vertical-align: middle; }
.aph-vt .aph-tbl .aph-letter td { text-align: center; font-weight: bold; padding: 1px; }
.aph-vt .aph-tbl .c { text-align: center; }
.aph-vt .aph-tbl .r { text-align: right; white-space: nowrap; }
.aph-vt .aph-tbl small { font-size: 10.5px; }
.aph-vt .c-stt { width: 5%; }
.aph-vt .c-ma { width: 14%; }
.aph-vt .c-dvt { width: 7%; }
.aph-vt .c-sl { width: 10%; }
.aph-vt .c-tien { width: 12%; }
.aph-vt .aph-sign-date { text-align: right; font-style: italic; margin-top: 10px; padding-right: 4%; }
.aph-vt .aph-sign td { text-align: center; padding-top: 4px; }
.aph-vt .aph-sign-name { margin-top: 70px; }
.aph-vt .aph-qh { width: 50%; text-align: center; }
.aph-vt .aph-lien { font-style: italic; margin-top: 2px; }
.aph-vt .aph-party { font-weight: bold; margin-top: 6px; }
.aph-vt .aph-tbl .aph-sum td { font-weight: bold; }
.aph-vt .aph-tbl .aph-sum .l { text-align: right; }
.aph-vt .c-lo { width: 11%; }
.aph-vt .aph-tc { line-height: 1.9; font-size: 13.5px; }
.aph-vt .aph-tong { width: 55%; margin-left: 45%; margin-top: -1px; }
.aph-vt .aph-tong .l { text-align: left; }
.aph-vt .aph-tbl th { color: #000; }

/* Chứng từ vận dụng TT133/TT99; giữ khổ giấy do người dùng chọn, không ép A5 cho phiếu dài. */
.aph-vt .aph-state { text-align:center; font-weight:bold; border:1px solid #555; padding:3px; margin:3px 0; }
.aph-vt .aph-head { page-break-inside:avoid; break-inside:avoid; }
.aph-vt thead { display:table-header-group; }
.aph-vt tr { page-break-inside:avoid; break-inside:avoid; }
.aph-vt .aph-sign { page-break-inside:avoid; break-inside:avoid; }
.aph-vt .aph-sign td { min-width:15%; height:92px; }
.aph-vt .aph-mau { overflow-wrap:break-word; }

html:
{#- Biên bản giao nhận hàng hóa, in từ Phiếu giao hàng: 2 liên trong một lần in (liên 1 giao khách,
    liên 2 công ty lưu). Đơn giá, thành tiền ĐÃ GỒM THUẾ GTGT (chị Dung chốt 30/09: không tách giá và thuế),
    tổng tiền thanh toán, số tiền bằng chữ.
    Thuê xe, nhà xe: thêm người vận chuyển ký. Phiếu nhận hàng trả lại (is_return): biên bản nhận lại
    hàng hóa, bên giao là khách hàng. -#}
{%- set cty = kh_aph_cong_ty(doc.company) -%}
{%- set tra = doc.is_return -%}
{%- set gn = kh_aph_giao_nhan(doc) -%}
{%- set dons = doc.items | map(attribute="against_sales_order") | select | unique | list -%}
{%- set thue = gn.method in ("Thuê xe, nhà xe", "Vận chuyển") -%}
{%- set cham = ".............................." -%}
{%- set dc = kh_aph_dia_chi(doc.shipping_address or doc.address_display) -%}
{%- set gia = kh_aph_gia_gom_thue(doc) -%}
{%- set tong = gia.tong -%}
{#- 0.11.1 (cờ kh_aph_sales_adjust): Q192 mặc định không giá; Q198 cột thực nhận khi có phiếu trả lại loại giao thiếu;
    R053/Q199 số lượng "bao + kg" hoặc ĐVT bán kèm quy đổi. Cờ tắt: in như cũ. -#}
{%- set an_gia = kh_aph_bbgn_an_gia(doc) -%}
{%- set tn = kh_aph_thuc_nhan(doc) -%}

{%- set pf = kh_aph_mau_info(doc.company) -%}
{%- macro ben_cty(nhan) -%}
  <div class="aph-party">{{ "BÊN NHẬN" if nhan else "BÊN GIAO" }} ({{ "Bên B" if nhan else "Bên A" }}): {{ cty.ten }}</div>
  {%- if cty.dia_chi %}<div>- Địa chỉ: {{ cty.dia_chi }}</div>{% endif %}
  {%- if cty.mst %}<div>- Mã số thuế: {{ cty.mst }}</div>{% endif %}
  <div>- Đại diện: {{ (gn.dispatcher or kh_aph_ten_nguoi(doc.owner)) | e }}</div>
{%- endmacro -%}

{%- macro ben_khach(nhan) -%}
  <div class="aph-party">{{ "BÊN NHẬN" if nhan else "BÊN GIAO" }} ({{ "Bên B" if nhan else "Bên A" }}): {{ doc.customer_name }}</div>
  <div>- Địa chỉ{{ " giao hàng" if nhan else "" }}: {{ dc or cham }}</div>
  {%- if doc.tax_id %}<div>- Mã số thuế: {{ doc.tax_id }}</div>{% endif %}
  <div>- {{ "Người nhận hàng" if nhan else "Người giao trả hàng" }}: {{ (gn.recipient or cham) | e }}</div>
{%- endmacro -%}

{%- macro lien(so, ten) -%}
<div class="aph-vt">
{% if doc.docstatus == 0 %}<div class="aph-state">BẢN NHÁP - CHƯA GHI SỔ</div>{% elif doc.docstatus == 2 %}<div class="aph-state">CHỨNG TỪ ĐÃ HỦY - CHỈ ĐỂ ĐỐI CHIẾU</div>{% endif %}
<table class="aph-head"><tr>
  <td><b>{{ cty.ten }}</b>{% if cty.dia_chi %}<br>{{ cty.dia_chi }}{% endif %}{% if cty.mst %}<br>MST: {{ cty.mst }}{% endif %}</td>
  <td class="aph-qh"><b>CỘNG HÒA XÃ HỘI CHỦ NGHĨA VIỆT NAM</b><br><b><u>Độc lập - Tự do - Hạnh phúc</u></b></td>
</tr></table>
<table class="aph-title"><tr>
  <td class="aph-center">
    <div class="aph-name">{{ "BIÊN BẢN NHẬN LẠI HÀNG HÓA" if tra else "BIÊN BẢN GIAO NHẬN HÀNG HÓA" }}</div>
    <div>Số: {{ doc.name }} &nbsp;–&nbsp; <span class="aph-date">{{ kh_aph_ngay(doc.posting_date) }}</span></div>
    <div class="aph-lien">{{ pf.nhan | e }}</div>
    <div class="aph-lien">Liên {{ so }}: {{ ten }}</div>
  </td>
</tr></table>

<div class="aph-info">
  {%- if tra %}
  <div>Căn cứ phiếu giao hàng số {{ doc.return_against or cham }}, hai bên giao nhận lại hàng hóa khách trả như sau.</div>
  {{ ben_khach(false) }}
  {{ ben_cty(true) }}
  {%- else %}
  <div>Căn cứ {% if dons %}đơn hàng số {{ dons | join(", ") }}{% else %}thỏa thuận mua bán{% endif %}
    {%- if doc.po_no %}; đơn đặt hàng của khách số {{ doc.po_no }}{% endif %}, hai bên giao nhận hàng hóa như sau.</div>
  {{ ben_cty(false) }}
  {%- if thue %}
  <div class="aph-party">NGƯỜI VẬN CHUYỂN: {{ ("Nhà xe " ~ doc.kh_aph_nha_xe) if doc.kh_aph_nha_xe else cham }}</div>
  <div>- Lái xe: {{ (gn.driver or cham) | e }} &nbsp; Điện thoại: {{ doc.kh_aph_sdt_lai_xe or "............" }} &nbsp; Biển số xe: {{ (gn.vehicle or "............") | e }}</div>
  {%- endif %}
  {{ ben_khach(true) }}
  {% if gn.current and gn.carrier %}<div>- Nhà xe: {{ gn.carrier | e }}; Điện thoại nhà xe: {{ gn.carrier_phone | e }}</div>{% endif %}
{% if gn.current and gn.authorization %}<div>- Khách chỉ định người nhận: {{ gn.authorization | e }}</div>{% endif %}
{% if gn.current %}<div>- Cách giao: {{ gn.method | e }}; Điện thoại người nhận: {{ (gn.phone or cham) | e }}; Thời điểm xuất: {{ (gn.time or cham) | e }}</div>{% endif %}
  {%- endif %}
</div>

<table class="aph-tbl">
  <thead>
    <tr>
      <th class="c-stt">STT</th>
      <th>Tên hàng hóa, quy cách</th>
      <th class="c-ma">Mã hàng</th>
      <th class="c-dvt">ĐVT</th>
      <th class="c-lo">Số lô</th>
      <th class="c-sl">Số lượng</th>
      {%- if tn %}<th class="c-sl">Thực nhận</th>{% endif %}
      {%- if not an_gia %}
      <th class="c-tien">Đơn giá{% if gia.co_thue %}<br><small>(đã gồm thuế GTGT)</small>{% endif %}</th>
      <th class="c-tien">Thành tiền{% if gia.co_thue %}<br><small>(đã gồm thuế GTGT)</small>{% endif %}</th>
      {%- endif %}
    </tr>
  </thead>
  <tbody>
  {%- for row in doc.items %}
    <tr>
      <td class="c">{{ loop.index }}</td>
      <td>{{ row.item_name }}</td>
      <td class="c">{{ row.item_code }}</td>
      <td class="c">{{ row.uom }}</td>
      <td class="c">{{ kh_aph_lo(row) }}</td>
      <td class="r">{{ kh_aph_sl_hien_thi(row) or kh_aph_so((row.qty or 0) | abs) }}</td>
      {%- if tn %}<td class="r">{{ kh_aph_so(tn.get(row.name, row.qty)) }}</td>{% endif %}
      {%- if not an_gia %}
      {%- set g = gia.dong[loop.index0] %}
      <td class="r">{{ kh_aph_so(g.don_gia, g.le) }}</td>
      <td class="r">{{ kh_aph_so(g.thanh_tien, 0) }}</td>
      {%- endif %}
    </tr>
  {%- endfor %}
    {%- if not an_gia %}
    <tr class="aph-sum"><td colspan="{{ 8 if tn else 7 }}" class="l">Tổng cộng tiền thanh toán{% if gia.co_thue %} (đã gồm thuế GTGT){% endif %}</td><td class="r">{{ kh_aph_so(tong, 0) }}</td></tr>
    {%- endif %}
  </tbody>
</table>
<div class="aph-info">
  {%- if not an_gia %}<div>- Số tiền viết bằng chữ: {{ kh_aph_bang_chu(tong) }}</div>{% endif %}
  {%- if tra %}
  <div>- Bên B đã nhận lại đủ số lượng hàng hóa trên. Tình trạng hàng, bao bì: {{ cham }}{{ cham }}</div>
  {%- else %}
  <div>- Bên B đã kiểm tra và nhận đủ số lượng hàng hóa trên, đúng chủng loại, quy cách, bao bì nguyên vẹn.
    Sai khác (nếu có): {{ cham }}{{ cham }}</div>
  {%- endif %}
  <div>- Biên bản lập thành 02 liên có giá trị như nhau: liên 1 giao khách hàng, liên 2 {{ cty.ten }} lưu.</div>
</div>

<table class="aph-sign"><tr>
  <td><b>ĐẠI DIỆN BÊN GIAO</b><br><i>(Ký, ghi rõ họ tên)</i></td>
  {%- if thue and not tra %}
  <td><b>NGƯỜI VẬN CHUYỂN</b><br><i>(Ký, ghi rõ họ tên)</i></td>
  {%- endif %}
  <td><b>ĐẠI DIỆN BÊN NHẬN</b><br><i>(Ký, ghi rõ họ tên)</i></td>
</tr></table>
</div>
{%- endmacro -%}

{{ lien(1, "Giao khách hàng") }}
<div style="page-break-after: always; break-after: page;"></div>
{{ lien(2, "Lưu tại công ty") }}
